databases.type:
map(object({
    encode      = optional(string, "utf8mb4")
    mode        = optional(string, "auto")
    description = optional(string, "")
  }))

accounts.type:
map(object({
    password           = string
    account_type       = optional(string, "Normal")
    description        = optional(string, "")
    account_privileges = optional(map(string), {})
  }))
